ds":[{"dataName":"存货名称.品牌","dataType":"文本"},{"dataName":"存货名称","dataType":"参照","refPanel":"INV","refField":"存货名称","displayField":"存货名称","refMulti":true,"filter":{"停用":false},"refMap":[{"from":"存货编码","to":"存货编码"},{"from":"规格型号","to":"规格型号"},{"from":"品牌","to":"存货名称.品牌"},{"from":"计量单位","to":"销售单位"},{"from":"参考成本","to":"单价"}],"refColumns":["存货编码","存货名称","规格型号","品牌","计量单位","参考成本","停用"]},{"dataName":"存货编码","dataType":"下拉框","options":["CP001","CP002","CP003","CP004","CP005"]},{"dataName":"规格型号","dataType":"文本"},{"dataName":"数量","dataType":"小数","defaultValue":0},{"dataName":"销售单位","dataType":"下拉框","options":["件","kg","套"],"defaultValue":"件"},{"dataName":"单价","dataType":"小数","defaultValue":0},{"dataName":"税率%","dataType":"小数","defaultValue":13},{"dataName":"含税单价","dataType":"小数","computed":true},{"dataName":"金额","dataType":"小数","computed":true},{"dataName":"含税金额","dataType":"小数","computed":true},{"dataName":"折扣金额","dataType":"小数","defaultValue":0},{"dataName":"预计交货日期","dataType":"日期"},{"dataName":"现存量","dataType":"小数","computed":true},{"dataName":"备注","dataType":"文本"}]}]}}') ON DUPLICATE KEY UPDATE config = VALUES(config);
